  'seo-for-financial-advisors-wealth-firms': { family: 'seo', industry: 'finance', title: 'SEO for Financial Advisors & Wealth Firms', description: 'Develop search content around your services and the questions prospective clients ask. Combine technical improvements with clear explanations and an agreed review process for financial claims.', focus: ['Specific advisory services and client needs', 'Approved educational content', 'Advisor and firm information', 'Relevant local visibility'], examples: [['Service-page improvement', 'Clarify the scope of an advisory service and connect it with related questions.'], ['Educational content plan', 'Plan useful articles around the firm’s expertise, with defined review responsibilities.']], faq: ['Do you publish financial content without our approval?', 'No. The content workflow includes agreed review stages, and your designated reviewer approves relevant claims before publication.'] },
  'seo-for-the-healthcare-medtech-industry': { family: 'seo', industry: 'healthcare', title: 'SEO for Healthcare & MedTech', description: 'Build search visibility around the people you need to reach. For clinics, that may mean local service information; for MedTech, it may mean product explanations for professional buyers.', focus: ['Distinguish clinic patients from MedTech buyers', 'Local clinic information where relevant', 'Product and use-case content for MedTech', 'Qualified review of health-related statements'], examples: [['Clinic service information', 'Improve pages explaining available services, practical details, and the appointment route.'], ['MedTech product content', 'Organise product information around professional use cases and buyer questions.']], faq: ['Do clinics and MedTech companies need the same SEO approach?', 'No. Their audiences and buying processes differ. The plan is based on the actual service or product and the people researching it.'] },

